:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.wsq-warn, .fqc-tax-warn) { margin-top: 12px; padding: 12px; border-left: 3px solid var(--amber-700); background: var(--amber-50); color: var(--amber-900); font-size: 13px; }
