/* Webstore quote cards; reference layout and assistant shell are shared. */
@layer components.pages {
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .banner-section-header--gap { margin-top: 28px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .quick-fact--accent { color: var(--ui-accent); font-weight: 600; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.webstore-quote-card, .fundraiser-quote-card) { padding: 16px; border: 1px solid var(--ui-line); border-radius: var(--radius-sm); margin-top: 12px; background: var(--ui-surface); }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.wsq-label, .fqc-label) { color: var(--ui-accent); font-size: 12px; font-weight: 600; margin-bottom: 8px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .wsq-pn { font-size: 14px; font-weight: 600; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.wsq-store-type, .fqc-donation-banner) { display: block; padding: 8px 12px; margin-block: 12px; background: var(--ui-tint); color: var(--ui-accent); font-size: 13px; border-radius: var(--radius-sm); }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.wsq-line, .fqc-line) { display: flex; justify-content: space-between; gap: 12px; padding-block: 8px; font-size: 14px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .v { white-space: nowrap; font-variant-numeric: tabular-nums; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .total { font-weight: 700; border-top: 1px solid var(--ui-line); }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .wsq-meta { border-top: 1px solid var(--ui-line); margin-top: 12px; padding-top: 12px; font-size: 13px; line-height: 1.6; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) :is(.wsq-warn, .fqc-tax-warn) { margin-top: 12px; padding: 12px; border-left: 3px solid var(--amber-700); background: var(--amber-50); color: var(--amber-900); font-size: 13px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .fqc-price { font-size: 28px; font-weight: 700; font-variant-numeric: tabular-nums; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .fqc-spec { font-size: 13px; color: var(--ui-muted); margin-block: 8px 12px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .tool-chip { font-size: 13px; color: var(--ui-muted); line-height: 1.5; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .web-search-results { border: 1px solid var(--ui-line); padding: 12px; border-radius: var(--radius-sm); margin-block: 8px; font-size: 13px; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .web-search-results a { overflow-wrap: anywhere; }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .share-toast.show { inset: auto 24px 24px auto; width: min(480px, calc(100% - 48px)); }
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .quote-save-status { margin: 0; padding: 12px 20px; flex-shrink: 0; border-top: 1px solid var(--amber-700); background: var(--amber-50); color: var(--amber-900); font-size: 13px; }

@media print {
:where([data-ui="unified"][data-specialty-calculator="webstore"]) .banner-section-header--gap { margin-top: 16px; }
}
}

